{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Conflicting reports of increases and decreases in rates of preterm birth (PTB) and stillbirth in the general population during the coronavirus disease 2019 (COVID-­ 19) pandemic have surfaced.",
      "reason": "The introduction clearly describes the current state of knowledge, highlighting conflicting reports regarding PTB and stillbirth rates during the pandemic."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The objective of our study was to conduct a living systematic review and meta-­ analyses of studies reporting pregnancy and neonatal outcomes by comparing the pandemic and pre-­ pandemic periods.",
      "reason": "The need for the review is explained by the objective to synthesize studies comparing pregnancy and neonatal outcomes between pandemic and pre-pandemic periods, addressing the conflicting reports mentioned."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "Recently, Chmielewska 59 et al reported results from a system - atic review and meta-­ analyses including studies evaluating studies assessing population-­ level impact during the pandemic period published up to January 8, 2021. ... With the availability of data from 13 more studies on PTB and nine more studies for stillbirth, the results have remarkably changed, although this could also partly relate to minor differences in study inclusion criteria and data extraction.",
      "reason": "The manuscript identifies a previous systematic review (Chmielewska et al.) and explains the need for the current review due to the availability of new data and the need for regular updates as a living systematic review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of observational studies comparing pregnancy outcomes during the pandemic vs. pre-pandemic, not a review of intervention effects, so a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review does not evaluate complex interventions or delivery contexts, so a logic model is not required."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The objective of our study was to conduct a living systematic review and meta-­ analyses of studies reporting pregnancy and neonatal outcomes by comparing the pandemic and pre-­ pandemic periods.",
      "reason": "The objective of the review is explicitly stated in the abstract."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies were included if they compared pregnancy outcomes between the COVID-­ 19 pandemic period and pre-­ pandemic time periods and reported on any of the outcomes of interest.",
      "reason": "The review compares pregnancy and neonatal outcomes between pandemic and pre-pandemic periods, which constitutes the PICO framework (Population: pregnant women/neonates; Intervention/Exposure: COVID-19 pandemic period; Comparison: pre-pandemic period; Outcome: pregnancy and neonatal outcomes)."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies were included if they compared pregnancy outcomes between the COVID-­ 19 pandemic period and pre-­ pandemic time periods and reported on any of the outcomes of interest. We excluded studies that only reported outcomes of pregnant women with COVID-­ 19.",
      "reason": "The manuscript specifies the inclusion criteria (comparison of pandemic vs. pre-pandemic periods) and exclusion criteria (studies only reporting on pregnant women with COVID-19)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We searched PubMed and Embase databases, reference lists of included articles, and personal files for studies published up to August 14, 2021. The search strategy... included any type of study design published in the English language",
      "reason": "The manuscript specifies the language (English) and the publication timeframe (up to August 14, 2021)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Full-text articles excluded, with reasons (n = 27) ... Different outcome (n = 5) ... No outcome data (n = 1)",
      "reason": "The PRISMA flow diagram (Figure 1) distinguishes between studies excluded because they reported different outcomes (not the ones of interest) and studies excluded because they had no outcome data (results not reported)."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Post-­ hoc subgroup analyses were conducted for the two primary outcomes after dividing studies into single-­ center (or selected hospitals/centers in an area), regional (statewide or province-­ wide) or national in scope.",
      "reason": "The manuscript specifies how studies were grouped for synthesis (subgroup analyses based on study setting: single-center, regional, or national)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "This review was designed to evaluate the impact of the COVID-­ 19 pandemic on pregnancy and neonatal outcomes and not to evaluate studies that report only on maternal COVID-­ 19 itself, which has been discussed in other reviews.",
      "reason": "The authors provide a clear rationale for the restriction on study eligibility regarding studies that only reported on pregnant individuals infected with COVID-19."
    }
  ],
  "confidence": 100
}

